<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title ?? 'Recruitment Portal') ?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-expand-lg navbar-dark bg-primary"><div class="container"><a class="navbar-brand" href="/">Recruitment Portal</a><div class="navbar-nav ms-auto"><?php if(session()->has('user_id')): ?><a class="nav-link" href="/dashboard">Dashboard</a><?php if(session('role')==='candidate'): ?><a class="nav-link" href="/profile">Profile</a><?php else: ?><a class="nav-link" href="/hr">HR</a><?php endif; ?><a class="nav-link" href="/logout">Logout</a><?php else: ?><a class="nav-link" href="/login">Login</a><a class="nav-link" href="/register">Register</a><?php endif; ?></div></div></nav><main class="container py-4"><?php foreach(['success','error'] as $k): if(session()->getFlashdata($k)): ?><div class="alert alert-<?= $k==='success'?'success':'danger' ?>"><?= esc(session()->getFlashdata($k)) ?></div><?php endif; endforeach; ?><?= $this->renderSection('content') ?></main></body></html>
